#include <stdio.h>



int main(void) {
    for (int n = 2; n <= 1000; n++) {
        int sum = 1;
        for (int d = 2; d <= n / 2; d++) if (n % d == 0) sum += d;
        if (sum == n) printf("%d ", n);
    }
    putchar('\n');
    return 0;
}
